{
    not: function(components, selector) {
        var i = 0,
            length = components.length,
            results = [],
            index = -1,
            component;
        for (; i < length; ++i) {
            component = components[i];
            if (!cq.is(component, selector)) {
                results[++index] = component;
            }
        }
        return results;
    },
    first: function(components) {
        var ret = [];
        if (components.length > 0) {
            ret.push(components[0]);
        }
        return ret;
    },
    last: function(components) {
        var len = components.length,
            ret = [];
        if (len > 0) {
            ret.push(components[len - 1]);
        }
        return ret;
    },
    // This filters for components which by definition and configuration are
    // theoretically focusable. It does not take into account the current app state.
    focusable: function(cmps) {
        var len = cmps.length,
            results = [],
            i = 0,
            c;
        for (; i < len; i++) {
            c = cmps[i];
            if (c.isFocusable && c.isFocusable()) {
                results.push(c);
            }
        }
        return results;
    },
    // This filters for components which are currently able to recieve focus.
    canfocus: function(cmps, value) {
        var len = cmps.length,
            results = [],
            i = 0,
            c;
        for (; i < len; i++) {
            c = cmps[i];
            if (c.canFocus && c.canFocus(false, value)) {
                results.push(c);
            }
        }
        return results;
    },
    "nth-child": function(c, a) {
        var result = [],
            m = nthRe.exec(a === "even" && "2n" || a === "odd" && "2n+1" || !nthRe2.test(a) && "n+" + a || a),
            f = (m[1] || 1) - 0,
            len = m[2] - 0,
            i, n, nodeIndex;
        for (i = 0; n = c[i]; i++) {
            // jshint ignore:line
            nodeIndex = i + 1;
            if (f === 1) {
                if (len === 0 || nodeIndex === len) {
                    result.push(n);
                }
            } else if ((nodeIndex + len) % f === 0) {
                result.push(n);
            }
        }
        return result;
    },
    scrollable: function(cmps) {
        var len = cmps.length,
            results = [],
            i = 0,
            c;
        for (; i < len; i++) {
            c = cmps[i];
            // Note that modern toolkit prefixes with an underscore.
            if (c.scrollable || c._scrollable) {
                results.push(c);
            }
        }
        return results;
    },
    visible: function(cmps, deep) {
        deep = deep === 'true';
        var len = cmps.length,
            results = [],
            i = 0,
            c;
        for (; i < len; i++) {
            c = cmps[i];
            // Note that modern toolkit prefixes with an underscore.
            if (c.isVisible(deep)) {
                results.push(c);
            }
        }
        return results;
    }
}

