                flex: 1,
                style: 'background-color: red;'
            },
            {
                xtype: 'panel',
                flex: 2,
                style: 'background-color: green'
            }
        ]
    });

Represents an HTML fragment template. Templates may be {@link #method!compile precompiled} for greater performance.

An instance of this class may be created by passing to the constructor either a single argument, or multiple
arguments:

# Single argument: String/Array

The single argument may be either a String or an Array:

- String:

      var t = new Ext.Template("<div>Hello {0}.</div>");
      t.append('some-element', ['foo']);

- Array:

  An Array will be combined with `join('')`.

      var t = new Ext.Template([
          '<div name="{id}">',
              '<span class="{cls}">{name:trim} {value:ellipsis(10)}</span>',
          '</div>',
      ]);
      t.compile();
      t.append('some-element', {id: 'myid', cls: 'myclass', name: 'foo', value: 'bar'});

# Multiple arguments: String, Object, Array, ...

Multiple arguments will be combined with `join('')`.

    var t = new Ext.Template(
        '<div name="{id}">',
            '<span class="{cls}">{name} {value}</span>',
        '</div>',
        // a configuration object:
        {
            compiled: true,      // {@link #method!compile #compile} immediately
        }
    );

# Notes

- For a list of available format functions, see {@link Ext.util.Format}.
- `{@link #cfg!disableFormats disableFormats}` reduces `{@link #method!apply #apply}` time when no formatting is required.

The template values. Can be an array if your params are numeric:

    var tpl = new Ext.Template('Name: {0}, Age: {1}');
    tpl.apply(['John', 25]);

or an object:

    var tpl = new Ext.Template('Name: {name}, Age: {age}');
    tpl.apply({name: 'John', age: 25});

The template values. Can be an array if your params are numeric:

    var tpl = new Ext.Template('Name: {0}, Age: {1}');
    tpl.apply(['John', 25]);

or an object:

    var tpl = new Ext.Template('Name: {name}, Age: {age}');
    tpl.apply({name: 'John', age: 25});

{@link Ext.TitleBar}'s are most commonly used as a docked item within an {@link Ext.Container}.

The main difference between a {@link Ext.TitleBar} and an {@link Ext.Toolbar} is that
the {@link #cfg!title #title} configuration is **always** centered horizontally in a {@link Ext.TitleBar} between
any items aligned left or right.

You can also give items of a {@link Ext.TitleBar} an `align` configuration of `{@link #cfg!left left}` or `{@link #cfg!right right}`
which will dock them to the `{@link #cfg!left left}` or `{@link #cfg!right right}` of the bar.

## Examples

    @example preview
    Ext.Viewport.add({
        xtype: 'titlebar',
        docked: 'top',
        title: 'Navigation',
        items: [
            {
                iconCls: 'add',
                align: 'left'
            },
            {
                iconCls: 'home',
                align: 'right'
            }
        ]
    });

    Ext.Viewport.setStyleHtmlContent(true);
    Ext.Viewport.setHtml('This shows the title being centered and buttons using align <i>left</i> and <i>right</i>.');

<br />

    @example preview
    Ext.Viewport.add({
        xtype: 'titlebar',
        docked: 'top',
        title: 'Navigation',
